using System.Runtime.CompilerServices;
using FusionNet.App.Localization;

namespace FusionNet.App.Views.Security;

internal static class MonitorUiStrings
{
    [ModuleInitializer]
    internal static void Register()
    {
        Loc.Add("Monitor.Text.SectionAppUsage","Recorded Explorer launches","التشغيل المسجل عبر Explorer");
        Loc.Add("Monitor.Text.MaintenanceFailed","Could not open the Windows page. Open Settings or Control Panel manually; availability depends on your Windows version.","تعذر فتح صفحة Windows. افتح الإعدادات أو لوحة التحكم يدويًا؛ توفر الصفحة يعتمد على إصدار Windows.");
        Loc.Add("Monitor.Ui.LaunchPrivacy","The scan also reads this Windows account's Explorer launch history and File History settings. They stay on this PC and are never sent to cloud AI.","يقرأ الفحص أيضًا سجل تشغيل البرامج عبر Explorer لهذا الحساب وإعدادات File History. تبقى على هذا الجهاز ولا تُرسل إلى الذكاء الاصطناعي السحابي.");
        Loc.Add("Monitor.Ui.UpdatesHint","Steam, Epic and other launchers can be selected above while only VALORANT or League of Legends is running. To stop a Windows Update download, choose Pause updates on the Windows page; Windows resumes it when you choose or when the pause ends.","يمكن اختيار Steam وEpic وباقي المشغّلات أعلاه عندما تعمل VALORANT أو League of Legends فقط. لإيقاف تنزيل تحديثات Windows اختر «إيقاف التحديثات مؤقتًا» في صفحة Windows؛ يستأنف Windows عند اختيارك أو بانتهاء المدة.");
        Loc.Add("Monitor.Ui.WindowsUpdateSettings","Pause Windows updates","إيقاف تحديثات Windows مؤقتًا");
        Loc.Add("Monitor.Ui.MaintenanceHeading","Review and manage in Windows","المراجعة والإدارة في Windows");
        Loc.Add("Monitor.Ui.MaintenanceDetails","Review Startup, installed apps and File History evidence in the scan sources tab first. These buttons open Windows management pages; you choose any disable, uninstall or backup change there. FusionNetPro does not apply those changes automatically.","راجع أدلة Startup والبرامج وFile History في تبويب مصادر الفحص أولًا. هذه الأزرار تفتح صفحات الإدارة في Windows؛ أنت تختار هناك أي تعطيل أو إزالة أو تغيير للنسخ. لا ينفذ FusionNetPro هذه التغييرات تلقائيًا.");
        Loc.Add("Monitor.Ui.StartupSettings","Manage Startup in Windows","إدارة Startup في Windows");
        Loc.Add("Monitor.Ui.InstalledAppsSettings","Manage installed apps","إدارة البرامج المثبتة");
        Loc.Add("Monitor.Ui.FileHistorySettings","Open File History","فتح File History");
        Loc.Add("Monitor.Ui.UsageEvidenceDetails","Security Scan includes current-account Explorer executable launch evidence when available. An old recorded launch is a review candidate, not proof an app was unused for six months. Names with known-folder tokens stay literal; cleared, disabled, unsupported and non-Explorer launches remain unknown. File History shows configuration/protection evidence, not a guaranteed successful backup.","يتضمن فحص الأمان التشغيل المسجل لملفات EXE عبر Explorer للحساب الحالي عند توفره. السجل القديم مرشح للمراجعة، وليس إثباتًا لعدم الاستخدام ستة أشهر. تبقى رموز المجلدات كما سجلها Windows؛ السجل المحذوف أو المعطّل والصيغ غير المدعومة والتشغيل خارج Explorer تبقى غير معروفة. يعرض File History أدلة الإعداد ونطاق الحماية، وليس ضمان نجاح نسخة.");
        Loc.Add("Monitor.Unavailable","Unavailable","غير متاح");
        Loc.Add("Monitor.Text.BrowserFailed","Could not open the browser. Use the official link in the app guide.","تعذر فتح المتصفح. راجع الرابط الرسمي في دليل البرنامج.");
        Loc.Add("Monitor.Format.Summary","Processes: {0} | Connections/ports: {1} | Alerts/notes: {2} | {3:HH:mm:ss}","العمليات: {0} | الاتصالات/المنافذ: {1} | التنبيهات والملاحظات: {2} | {3:HH:mm:ss}");
        Loc.Add("Monitor.Format.Duration","Duration: {0} minutes. Direction: Outbound. Action: full block for every instance of the executable; not rate limiting.","المدة: {0} دقيقة. الاتجاه: Outbound. الإجراء: حظر كامل لكل نسخ الملف؛ لا تقييد سرعة.");
        Loc.Add("Monitor.Format.Target","\n{0}\n{1}\n{2}\nReason: you selected an eligible background app; this does not mean it is malicious.\n{3}","\n{0}\n{1}\n{2}\nسبب الإجراء: اخترته من تطبيقات الخلفية المؤهلة؛ لا استنتاج أنه ضار.\n{3}");
        Loc.Add("Monitor.Format.RecoveryTask","\nRecovery task: {0}\nRuns as SYSTEM at boot and every minute when needed. A separate helper watches duration, game and app exit. Protected local state is saved in ProgramData before the first rule. Session rules and the task are removed during restoration.","\nمهمة الاسترجاع: {0}\nتعمل بحساب SYSTEM عند الإقلاع وكل دقيقة عند الحاجة. مساعد منفصل يراقب انتهاء المدة/اللعبة/التطبيق. يُحفظ سجل حالة محلي محمي في ProgramData قبل أول قاعدة. تُزال القواعد والمهمة عند الاسترجاع.");
        Loc.Add("Monitor.Format.Session","{0} ({1}) | Rules: {2} | Elapsed: {3:hh\\:mm\\:ss}\n{4}","{0} ({1}) | القواعد: {2} | المدة المنقضية: {3:hh\\:mm\\:ss}\n{4}");
        Loc.Add("Monitor.Format.Suggestion","Selected {0} eligible apps/paths among the highest measured total transfer rates. Review the selection; nothing is blocked. Games, launchers and unknown roles are excluded.","حُدد {0} تطبيق/مسار ضمن الأعلى في مجموع الاستهلاك المقاس المتاح. راجع اختيارك؛ لم يُحظر شيء. لا تشمل الاقتراحات الألعاب أو المشغلات أو الدور المجهول.");
        Loc.Add("Monitor.Format.StorageConsent","Only this folder and its descendants will be read:\n{0}\n\nAbout 20 seconds and 20,000 files maximum. Photo content comparison: {1}. Links are excluded. No cloud upload or deletion. Do you approve?","سيُقرأ المجلد التالي ومجلداته الفرعية فقط:\n{0}\n\nحد الفحص نحو20 ثانية و20000 ملف. مقارنة محتوى الصور: {1}. تُستثنى الروابط. لا إرسال سحابي ولا حذف. هل توافق؟");
        Loc.Add("Monitor.Format.EtwSample","ETW sample: {0:F1} seconds, ended {1:HH:mm:ss}. ","عينة ETW: {0:F1} ثانية، انتهت {1:HH:mm:ss}. ");
        Loc.Add("Monitor.Format.CloudConsent","Provider: {0}\nModel: {1}\n\nThe input below is sent with fixed instructions requesting an Arabic explanation, store=false and no execution tools. API charges may apply. Input excludes process names, paths, IP addresses, commands and keys. The provider retention policy applies.\n\n{2}","الموفر: {0}\nالنموذج: {1}\n\nسيُرسل input أدناه مع تعليمات ثابتة للشرح بالعربية، store=false ودون أدوات تنفيذ. قد تحتسب رسوم API. لا تُرسل أسماء العمليات أو المسارات أو IP أو أوامر التشغيل أو المفاتيح في input. سياسة احتفاظ الموفر هي المرجع.\n\n{2}");
        Loc.Add("Monitor.Format.Identity","Signature: {0}\n{1}\n{2}\n","التوقيع: {0}\n{1}\n{2}\n");
        Loc.Add("Monitor.Text.PhotoComparisonYes","Yes, up to 100 MB of candidate photo files","نعم، حتى100MB من ملفات الصور المرشحة للتطابق");
        Loc.Add("Monitor.Text.PhotoComparisonNo","No","لا");
        Loc.Add("Monitor.Text.StorageConsentTitle","Approve storage inspection","موافقة تحليل التخزين");
        Loc.Add("Monitor.Text.NoConnections","No observed ports or connections in this sample","لا منافذ أو اتصالات مرصودة في هذه العينة");
        Loc.Add("Monitor.Text.Eligible","Eligible for review; verified again before applying","مؤهل للمعاينة؛ يعاد التحقق قبل التطبيق");
        Loc.Add("Monitor.Text.UdpUnavailable","UDP destination unavailable","وجهة UDP غير متاحة");
        Loc.Add("Monitor.Text.SourceAvailable","Available within source limits","متاح ضمن حدود المصدر");
        Loc.Add("Monitor.Text.Partial","Partial","جزئي");
        Loc.Add("Monitor.Text.InitialStatus", "Read only. Scan locally; no automatic changes or cloud requests.", "قراءة فقط. اضغط فحص لجمع البيانات محليًا؛ لا تغييرات تلقائية ولا إرسال سحابي.");
        Loc.Add("Monitor.Text.NoSession", "No Game Boost session.", "لا توجد جلسة Game Boost.");
        Loc.Add("Monitor.Text.InitialAi", "Cloud analysis is optional. Local scans work without an API key.", "التحليل السحابي اختياري. الفحص المحلي يعمل بلا مفتاح API.");
        Loc.Add("Monitor.Text.NoApproval", "No preview has been approved in this run.", "لا توجد معاينة موافق عليها في هذا التشغيل.");
        Loc.Add("Monitor.Text.InitialStorage", "Choose a folder for manual inspection only. No automatic cleanup or deletion.", "اختر مجلدًا للفحص اليدوي فقط. لا حذف أو تنظيف تلقائي.");
        Loc.Add("Monitor.Text.SecurityTitle", "Security Monitor — local analysis", "Security Monitor — مراقب الأمان المحلي");
        Loc.Add("Monitor.Text.GameTitle", "Game Boost — reviewed gaming session", "Game Boost — جلسة لعب آمنة");
        Loc.Add("Monitor.Text.NoResults", "No results yet.", "لا توجد نتائج بعد.");
