        Loc.Add("Monitor.Text.SourcesLabel", "Available sources", "مصادر متاحة");
        Loc.Add("Monitor.Text.InitialEmpty", "Start a scan to see processes and resources. No automatic changes or cloud requests.", "ابدأ بالفحص لعرض العمليات ومواردها. لا تغييرات أو إرسال سحابي تلقائي.");
        Loc.Add("Monitor.Text.FilteredEmpty", "No processes match the current filters. Change the search or filters; missing readings are not zero.", "لا عمليات مطابقة للمرشحات الحالية. غيّر البحث أو عطّل المرشح؛ البيانات المفقودة لا تُعامل كصفر.");
        Loc.Add("Monitor.Text.Scanning", "Collecting a bounded local sample. Defender is not scanning and settings are unchanged.", "جارٍ جمع عينة محلية محدودة. لا يجري تشغيل فحص Defender أو تغيير إعدادات.");
        Loc.Add("Monitor.Text.ScanComplete", "Available data collected. Review source coverage; no alerts is not a security certificate.", "اكتمل جمع البيانات المتاحة. راجع تغطية كل قسم؛ غياب التنبيهات ليس شهادة أمان.");
        Loc.Add("Monitor.Text.ScanCancelled", "Scan cancelled; settings are unchanged. Previous results keep their original timestamp.", "أُلغي الفحص؛ لم تتغير إعدادات الجهاز. النتائج السابقة، إن وجدت، محفوظة مع وقتها.");
        Loc.Add("Monitor.Text.ScanFailed", "Could not complete the scan. Visible results are from the previous scan; no changes were made.", "تعذر إكمال الفحص. أي نتائج ظاهرة تعود إلى وقت الفحص السابق؛ لم تُنفّذ تغييرات.");
        Loc.Add("Monitor.Text.LegacyPending", "Stop legacy Fusion and restore its changes before starting Game Boost.", "أوقف Fusion القديم واستعد تغييراته قبل Game Boost.");
        Loc.Add("Monitor.Text.SelectTargets", "Select between one and ten eligible apps first.", "حدد من تطبيق واحد إلى عشرة تطبيقات مؤهلة أولًا.");
        Loc.Add("Monitor.Text.InvalidDuration", "Enter a whole duration from 1 to 360 minutes.", "أدخل مدة صحيحة من دقيقة إلى 360 دقيقة.");
        Loc.Add("Monitor.Text.PreviewHeading", "Preview of changes — do you approve?\n\n", "معاينة التغييرات — هل توافق؟\n\n");
        Loc.Add("Monitor.Text.RecoveryLimits", "\nIf both app and helper crash, restoration waits for the next scheduler attempt; Task Scheduler must be available. Windows requests administrator access for the helper only. No changes to general Firewall policy, DNS or services.", "\nتعطل المساعد والتطبيق معًا يؤخر الاسترجاع إلى محاولة المجدول التالية؛ توفر خدمة Task Scheduler مطلوب. سيطلب Windows صلاحية المسؤول للمساعد فقط. لا تغيير لسياسات Firewall العامة أو DNS أو الخدمات.");
        Loc.Add("Monitor.Text.ConsentTitle", "Game Boost approval — review the complete list", "موافقة Game Boost — راجع القائمة كاملة");
        Loc.Add("Monitor.Text.ApproveSession", "Approve and start session", "أوافق وأبدأ الجلسة");
        Loc.Add("Monitor.Text.ApprovalRecord", "Last approved preview (check session state to see whether it was applied or restored):\n", "آخر معاينة وافقت عليها (راجع حالة الجلسة لمعرفة هل طُبّقت أو استُعيدت):\n");
        Loc.Add("Monitor.Text.NoSuggestion", "No eligible measured transfer activity. Take an ETW sample first; connection counts cannot drive suggestions.", "لا يوجد نشاط نقل مقاس مؤهل للاقتراح. شغّل عينة ETW أولًا؛ لا اقتراح من عدد الاتصالات.");
        Loc.Add("Monitor.Text.ChooseFolder", "Choose a local folder to inspect storage without deleting files", "اختر مجلدًا محليًا لتحليل التخزين دون حذف");
        Loc.Add("Monitor.Text.StorageBusy", "Reading the selected folder...", "جارٍ قراءة المجلد المختار...");
        Loc.Add("Monitor.Text.StorageCancelled", "Storage inspection cancelled. No file was deleted.", "أُلغي تحليل التخزين. لم يُحذف أي ملف.");
        Loc.Add("Monitor.Text.StorageFailed", "Could not finish inspecting the selected folder; no file was deleted.", "تعذر إكمال تحليل المجلد المحدد؛ لم يُحذف أي ملف.");
        Loc.Add("Monitor.Text.ChecklistTitle", "Monthly maintenance checklist — run manually at the start of the month", "قائمة الصيانة الشهرية — تُشغّل يدويًا في أول الشهر");
        Loc.Add("Monitor.Text.Checklist", "1. Scan CPU/RAM and processes above 5%; compare several samples.\n2. Review Startup, services and tasks; do not disable unfamiliar components.\n3. Review Defender status and active/historical detections in Windows Security.\n4. Sample ETW when needed and review high-transfer apps before gaming.\n5. Inspect a selected folder for the 20 largest files/folders, old downloads and installer candidates. No automatic deletion.\n6. Missing app usage history does not prove an app was unused for six months.\n7. Verify backup destination and last success in Windows Backup/File History, then try restoring a small file. A running service does not prove a backup.\n8. Save the local report and compare with the previous month.\n\nThis version does not schedule monthly scans; this is the manual alternative. The Game Boost task is for recovery only, not monthly scanning.", "1. شغّل Scan وراجع CPU/RAM والعمليات فوق5%؛ قارن أكثر من عينة.\n2. راجع Startup والخدمات والمهام؛ لا تعطّل مكوّنًا لا تعرفه.\n3. راجع حالة Defender والكشوفات النشطة والتاريخية من Windows Security.\n4. شغّل عينة ETW عند الحاجة وراجع التطبيقات الأكثر نقلًا قبل جلسة اللعب.\n5. اختر مجلدًا لتحليل التخزين؛ راجع أكبر20 ملفًا ومجلدًا والتنزيلات القديمة ومرشحات المثبتات. لا حذف تلقائي.\n6. راجع التطبيقات المثبتة. عدم توفر سجل استخدام لا يعني أن تطبيقًا لم يُستخدم خلال6 أشهر.\n7. تحقق في Windows Backup/File History من وجهة النسخة وتاريخ نجاحها، ثم جرّب استرجاع ملف صغير. حالة الخدمة وحدها لا تثبت وجود نسخة.\n8. احفظ تقرير الفحص المحلي وقارن الملاحظات بالشهر السابق.\n\nلا توجد جدولة فحص شهري تلقائي في هذه النسخة؛ هذه القائمة هي البديل اليدوي. مهمة Game Boost الوحيدة مخصصة للاسترجاع، وليست فحصًا شهريًا.");
        Loc.Add("Monitor.Text.Done", "Done", "تم");
        Loc.Add("Monitor.Text.EtwConsent", "Windows requests administrator access for a separate helper for about five seconds. It enables network ETW to count bytes by PID (TCP/UDP, IPv4/IPv6), without packet contents or Firewall changes. Results are stored locally in ProgramData and the trace closes on normal helper exit. Force-terminating the helper can leave an orphan ETW session until restart. Do you approve?", "سيطلب Windows صلاحية المسؤول لعامل قياس منفصل لمدة خمس ثوانٍ تقريبًا. يُفعّل مصدر ETW للشبكة فقط لعدّ bytes حسب PID (TCP/UDP، IPv4/IPv6)، دون تسجيل محتوى الحزم أو تغيير قواعد Firewall. تُحفظ النتيجة محليًا في ProgramData وتُغلق جلسة التتبع عند انتهاء العامل طبيعيًا. الإنهاء القسري للعامل قد يترك جلسة ETW يتيمة حتى إعادة التشغيل. هل توافق؟");
        Loc.Add("Monitor.Text.EtwConsentTitle", "Approve network usage sampling", "موافقة قياس استهلاك الشبكة");
        Loc.Add("Monitor.Text.EtwBusy", "Collecting an optional ETW sample; no blocking or DNS changes.", "جارٍ جمع عينة ETW اختيارية؛ لا حظر ولا تعديل DNS.");
        Loc.Add("Monitor.Text.EtwComplete", "Values are sample averages. Use the measured-activity filter; CPU and inventory remain from the previous Scan.", "تعرض القيم متوسط العينة. استخدم مرشح النشاط المقاس؛ CPU وبيانات الفحص من وقت Scan السابق.");
        Loc.Add("Monitor.Text.EtwIncomplete", "Coverage is incomplete or no attributable events arrived; rates are unavailable.", "التغطية غير مكتملة أو لم تصل أحداث قابلة للإسناد؛ السرعات غير متاحة.");
        Loc.Add("Monitor.Text.EtwCancelled", "Stopped waiting for the sample. If started, the independent helper finishes its short window; no substitute values.", "أُلغي انتظار العينة. العامل المستقل، إن بدأ، ينتهي بعد نافذته القصيرة؛ لا قيم بديلة.");
        Loc.Add("Monitor.Text.EtwFailed", "No reliable new network sample. Previous readings retain their timestamp and are not current measurements.", "لم تتوفر عينة شبكة جديدة موثوقة. أي قيم سابقة تحمل وقت عينتها وليست قياسًا حاليًا.");
        Loc.Add("Monitor.Text.ModelRequired", "Enter your provider's model name.", "أدخل اسم النموذج لدى موفرك.");
        Loc.Add("Monitor.Text.ProviderSaved", "Provider saved. Any supplied key is encrypted for this Windows account and bound to this endpoint; nothing is sent automatically.", "حُفظ إعداد الموفر. المفتاح، إن أدخلته، مشفّر بحساب Windows ومربوط بالرابط المحدد؛ لا إرسال تلقائي.");
        Loc.Add("Monitor.Text.KeyRemoved", "Removed the stored key for this endpoint only.", "أُزيل المفتاح المخزّن لهذا الرابط فقط.");
