        Loc.Add("Monitor.Text.CloudAdvisory", "Cloud advisory analysis — requires human verification:\n", "تحليل سحابي استشاري — يحتاج تحققًا بشريًا:\n");
        Loc.Add("Monitor.Text.CloudCancelled", "Cloud analysis timed out or was cancelled; the local scan report is still available.", "انتهت مهلة التحليل السحابي أو أُلغي الطلب؛ تقرير الفحص المحلي ما زال متاحًا.");
